//! `add_speed_ramp`, the speed ramp presets (spec §11 SR-23, #340): a Ramp
//! Up, a Ramp Down, a Speed Dip or a Speed Burst made in ONE step out of
//! ordinary Speed actions — actions whose `end` names a `speed` (SR-1,
//! SR-10) — so undo, the band drags, the inspector and the plan read them
//! exactly as they read one made by hand.
//!
//! **Everything is CLIP time**, as `add_action`'s `at` is: `from` and `to`
//! are both given or both absent, which is the clip's whole length [0, D).
//! The BASE b is the rate the clip plays at `from` before the edit
//! (`rate_in_force`), which after an earlier speed action is that action's
//! end rate and not `clip.speed`.
//!
//! - **Ramp Up / Ramp Down** — one action [from, to) ending at `rate`: the
//!   clip ramps from b to it and holds it after.
//! - **Speed Dip / Speed Burst** — two actions of length r each, r being
//!   `(to − from)·(1 − hold)/2` snapped DOWN onto the grid and never under
//!   one frame: [from, from + r) ending at `rate`, and [to − r, to) ending
//!   at b. The span between them holds the target; at `hold` 0 they abut.
//!
//! "Up" and "down" are about the base rate, not about time: Up and Burst
//! need a rate above b, Down and Dip one below it. A ramp mirrored in TIME
//! would have to change the clip's own `speed`, and a preset makes only
//! Speed actions.
//!
//! **The lane's one rule holds** (spec §5.4): an action the span runs into
//! is a REFUSAL naming it, never replaced — a replacement would drop the
//! action's other keys — and the span tested is the WHOLE of [from, to)
//! for every shape, so an action sitting in a dip's hold gap is refused as
//! well: the gap must hold the target. **The clip keeps its slot** (SR-2):
//! a preset that would read past the media's end is refused naming the
//! largest rate that fits, through R1's solve (`largest_fitting_rate`).
//!
//! Errs come first, then the refusals, each in the order SR-23 lists them;
//! every sentence the lane already has is reused, not restated.

use serde::{Deserialize, Serialize};
use serde_json::{json, Value};

use crate::edit_action::{action_overlaps, action_past_end, overlapping_action};
use crate::edit_action_speed::read_speed_end;
use crate::edit_clip_timing::{SPEED_MAX, SPEED_MIN};
use crate::model::{Action, Clip, Curve, Project};
use crate::outcome::Outcome;
use crate::speed_map::rate_in_force;
use crate::time::Ticks;

/// The four presets (SR-23 (c)).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum RampShape {
    RampUp,
    RampDown,
    SpeedDip,
    SpeedBurst,
}

/// A dip's or a burst's hold when `hold` is absent: half the span at the
/// target, a quarter each side ramping.
pub const HOLD_DEFAULT: f64 = 0.5;
/// The most of the span a hold may take. Below 1 so each ramp keeps some
/// length to ease over; one frame is its floor in any case.
pub const HOLD_MAX: f64 = 0.9;

impl RampShape {
    /// The shape as a refusal names it.
    fn name(self) -> &'static str {
        match self {
            RampShape::RampUp => "a ramp up",
            RampShape::RampDown => "a ramp down",
            RampShape::SpeedDip => "a speed dip",
            RampShape::SpeedBurst => "a speed burst",
        }
    }

    /// Whether the target must lie ABOVE the base rate (Up and Burst) or
    /// below it (Down and Dip).
    fn rises(self) -> bool {
        matches!(self, RampShape::RampUp | RampShape::SpeedBurst)
    }

    /// Whether the shape returns to the base rate: two actions and a hold.
    fn returns(self) -> bool {
        matches!(self, RampShape::SpeedDip | RampShape::SpeedBurst)
    }
}

/// One Speed action: a span ending at `rate`.
fn speed_action(id: u32, start: Ticks, duration: Ticks, curve: Curve, rate: f64) -> Action {
    Action {
        id,
        start,
        duration,
        curve,
        end: json!({ "speed": rate }),
    }
}

impl Project {
    /// The speed ramp presets (the module doc, spec §11 SR-23).
    #[allow(clippy::too_many_arguments)]
    pub fn add_speed_ramp(
        &self,
        clip: u32,
        shape: RampShape,
        rate: f64,
        from: Option<Ticks>,
        to: Option<Ticks>,
        curve: Option<Curve>,
        hold: Option<f64>,
    ) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?.clone();
        // Only a media clip has a window to read at a rate; the sentence is
        // the end-rate door's own (`edit_action_speed.rs`).
        read_speed_end(&target, &Value::from(1.0))?;
        if !(rate.is_finite() && rate > 0.0) {
            return Err(format!("rate must be a positive number, not {rate}"));
        }
        let rate = rate.clamp(SPEED_MIN, SPEED_MAX);
        let (from, to) = match (from, to) {
            (None, None) => (0, target.duration),
            (Some(given_from), Some(given_to)) => {
                let from = self.snapped(given_from);
                if from < 0 {
                    return Err(format!("from must not be negative, not {given_from}"));
                }
                (from, self.snapped(given_to))
            }
            _ => return Err("from and to are given together or not at all".to_string()),
        };
        if to <= from {
            return Err(format!("to must be after from, not {to} against {from}"));
        }
        if hold.is_some() && !shape.returns() {
            return Err("hold is for speed_dip and speed_burst only".to_string());
        }

        let length = to - from;
        if to > target.duration {
            return Ok(Outcome::Refused(action_past_end(
                clip,
                from,
                length,
                target.duration,
            )));
        }
        // ONE test over the whole span, whatever the shape (SR-23 (e)).
        if let Some(other) = overlapping_action(&target.actions, None, from, length) {
            return Ok(Outcome::Refused(action_overlaps(clip, other)));
        }
        let frame = self.frame();
        if shape.returns() && length < 2 * frame {
            return Ok(Outcome::Refused(format!(
                "{} needs a span of at least two frames ({} ticks); {from} to {to} ticks is \
                 {length}",
                shape.name(),
                2 * frame
            )));
        }
        let base = rate_in_force(&target, from);
        let wrong_way = if shape.rises() {
            rate <= base
        } else {
            rate >= base
        };
        if wrong_way {
            return Ok(Outcome::Refused(format!(
                "{} needs a rate {} ×{base}, the rate clip {clip} plays at {from} ticks into \
                 it; ×{rate} is not",
                shape.name(),
                if shape.rises() { "above" } else { "below" }
            )));
        }

        let mut next = self.clone();
        let first = next.allocate_id();
        let second = shape.returns().then(|| next.allocate_id());
        let curve = curve.unwrap_or(Curve::EaseInOut);
        // A NaN hold reads as the default; any other is clamped into range.
        let hold = match hold {
            Some(h) if !h.is_nan() => h.clamp(0.0, HOLD_MAX),
            _ => HOLD_DEFAULT,
        };
        let ramp = self
            .snapped_down(((length as f64) * (1.0 - hold) / 2.0) as Ticks)
            .max(frame);
        // The clip with the preset at target rate `x`: the one closure the
        // edit and the fit both build from, so they cannot disagree.
        let build = |x: f64| -> Clip {
            let mut out = target.clone();
            match second {
                None => out
                    .actions
                    .push(speed_action(first, from, length, curve, x)),
                Some(second) => {
                    out.actions.push(speed_action(first, from, ramp, curve, x));
                    out.actions
                        .push(speed_action(second, to - ramp, ramp, curve, base));
                }
            }
            out
        };
        let after = build(rate);
        // A linked clip's rate is refused (spec §11 AU-94).
        if let Some(why) = self.linked_rate_refusal(&target, &after) {
            return Ok(Outcome::Refused(why));
        }
        if let Some(over) = self.overrun(&after) {
            let floor_k = if shape.rises() {
                (base * 1000.0).floor() as i64 + 1
            } else {
                (SPEED_MIN * 1000.0).round() as i64
            };
            let head = format!(
                "{} to ×{rate} would read clip {clip} {over} ticks past the end of its media",
                shape.name()
            );
            return Ok(Outcome::Refused(
                match self.largest_fitting_rate(&build, rate, floor_k) {
                    Some(fit) => format!("{head}; the largest rate that fits is ×{fit}"),
                    None if shape.rises() => format!("{head}, and no rate above ×{base} fits"),
                    None => format!("{head}, and no rate down to ×0.1 fits"),
                },
            ));
        }
        if let Some(slot) = next.clip_mut(clip) {
            *slot = after;
        }
        self.finish(next)
    }
}
//! `set_action_end`'s `speed` arm (format version 27, spec §11 SR-10), and
//! the refusals every action op that can move a ramped clip's out point
//! answers (SR-2, the road map's C).
//!
//! `speed` is a number at the TOP of an action's `end`, beside the groups:
//! the rate the clip ramps to along the action's curve and holds after
//! (`speed_map.rs`). It is a door of its own, as `graphic` is
//! (`edit_action_graphic.rs`): not a property group, so `check_end_patch`
//! steps over it and this file reads it. A finite number is clamped to
//! ×0.1–×1000 as `set_speed` clamps; any other kind is an `Err`, and so is a
//! rate on a clip that is not a media clip, which has no window to read at
//! one; a `null` removes it, as it removes any key.
//!
//! **The clip keeps its slot** (SR-2): a ramp edit never moves `start` or
//! `duration`, it changes how much source the clip reads, `in + S(D)`. An
//! edit that would read past the media's end is REFUSED, naming what fits:
//! the largest end rate (R1) — S(D) is affine in one action's end rate, so
//! two readings solve it — or, when no rate down to ×0.1 fits, the latest
//! clip end at ×0.1 (R2); and for a retime, a removal or an end rate taken
//! away, the latest clip end (R3).

use serde_json::Value;

use crate::edit_clip_timing::{SPEED_MAX, SPEED_MIN};
use crate::export::describe;
use crate::model::{Clip, Project, Source};
use crate::speed_map::SpeedMap;
use crate::time::Ticks;

/// Reads a patch's `speed` for `clip`: `None` for a `null` (remove it), the
/// clamped rate for a number. `Err` for any other JSON kind, then for a
/// clip that is not a media clip.
pub(crate) fn read_speed_end(clip: &Clip, value: &Value) -> Result<Option<f64>, String> {
    if value.is_null() {
        return Ok(None);
    }
    let Some(rate) = value.as_f64() else {
        return Err(format!("speed must be a number, not {}", describe(value)));
    };
    if !matches!(clip.source, Source::Media { .. }) {
        return Err(format!(
            "clip {} is not a media clip, and only a media clip's action can end at a speed",
            clip.id
        ));
    }
    Ok(Some(rate.clamp(SPEED_MIN, SPEED_MAX)))
}

/// `clip` with action `action`'s end rate set to `rate`.
fn ending_at(clip: &Clip, action: u32, rate: f64) -> Clip {
    let mut out = clip.clone();
    if let Some(found) = out.actions.iter_mut().find(|a| a.id == action) {
        if let Value::Object(end) = &mut found.end {
            end.insert("speed".to_string(), Value::from(rate));
        }
    }
    out
}

/// The `{}` a refusal names a rate in, on the 0.001 grid it was found on.
fn thousandths(k: i64) -> f64 {
    k as f64 / 1000.0
}

impl Project {
    /// The latest clip END that fits: the clip's start plus S⁻¹ of what the
    /// file holds past `in`, snapped DOWN onto the grid, never before the
    /// start.
    fn latest_fitting_end(&self, clip: &Clip) -> Ticks {
        let Some((source_in, file)) = self.window_of(clip) else {
            return clip.start;
        };
        let remaining = file.saturating_sub(source_in).max(0) as f64;
        let fits = match SpeedMap::of(clip) {
            Some(map) => map.time_at(remaining),
            None if clip.speed.is_finite() && clip.speed > 0.0 => {
                let t = (remaining / clip.speed).floor();
                if t.is_finite() {
                    t as Ticks
                } else {
                    0
                }
            }
            None => remaining as Ticks,
        };
        self.snapped_down(clip.start.saturating_add(fits))
            .max(clip.start)
    }

    /// The largest end rate on the 0.001 grid, below `rate`, at which
    /// action `action` of `after` reads inside its file: R1's solve, then
    /// its step down. `None` when none down to ×0.1 does. Read by R1 and by
    /// a split's second half (spec §11 SR-18 (e)).
    pub(crate) fn largest_fitting_end_rate(
        &self,
        after: &Clip,
        action: u32,
        rate: f64,
    ) -> Option<f64> {
        let floor = (SPEED_MIN * 1000.0).round() as i64;
        self.largest_fitting_rate(&|x| ending_at(after, action, x), rate, floor)
    }

    /// The largest rate x on the 0.001 grid, below `rate` and at or above
    /// `floor_k` thousandths, at which the clip `at_rate(x)` reads inside
    /// its file: R1's solve, then its step down. `None` when none does.
    /// `at_rate` must make S(D) affine in x — one action's end rate
    /// (`largest_fitting_end_rate`), or a preset's target, which every
    /// piece it builds ramps to, holds or ramps from (`add_speed_ramp`,
    /// spec §11 SR-23 (g)).
    pub(crate) fn largest_fitting_rate(
        &self,
        at_rate: &dyn Fn(f64) -> Clip,
        rate: f64,
        floor_k: i64,
    ) -> Option<f64> {
        let probe = at_rate(rate);
        let (source_in, file) = self.window_of(&probe)?;
        let fits = |x: f64| self.overrun(&at_rate(x)).is_none();
        // S(D) = α + β·x in the rate x: read at two rates in range, solved
        // for the file's remainder.
        let read = |x: f64| SpeedMap::of(&at_rate(x)).map(|m| m.source_at(probe.duration));
        let solved = match (read(SPEED_MIN), read(1.0)) {
            (Some(low), Some(one)) => {
                let beta = (one - low) / (1.0 - SPEED_MIN);
                let alpha = low - SPEED_MIN * beta;
                let remaining = file.saturating_sub(source_in) as f64;
                (beta > 0.0).then(|| (remaining - alpha) / beta)
            }
            _ => None,
        };
        let x = solved.filter(|x| x.is_finite())?;
        // Floored to 0.001, never at or above the rate that overran, then
        // stepped down a thousandth until it fits. The millionth keeps a
        // solve that lands a hair under an exact thousandth (×4 read as
        // 3.9999999) on it; the step down catches the rest.
        let below = (rate * 1000.0).ceil() as i64 - 1;
        let mut k = ((x * 1000.0 + 1e-6).floor() as i64).min(below).max(floor_k);
        while k >= floor_k {
            if fits(thousandths(k)) {
                return Some(thousandths(k));
            }
            k -= 1;
        }
        None
    }

    /// R1 / R2: `after` is the clip with action `action` ending at `rate`
    /// (already clamped). `None` when it fits.
    pub(crate) fn end_rate_refusal(&self, after: &Clip, action: u32, rate: f64) -> Option<String> {
        let over = self.overrun(after)?;
        let clip = after.id;
        if let Some(fitting) = self.largest_fitting_end_rate(after, action, rate) {
            return Some(format!(
                "ending action {action} at ×{rate} would read clip {clip} {over} ticks past the \
                 end of its media; the largest end rate that fits is ×{fitting}"
            ));
        }
        let end = self.latest_fitting_end(&ending_at(after, action, SPEED_MIN));
        Some(format!(
            "ending action {action} at ×{rate} would read clip {clip} {over} ticks past the end \
             of its media, and no end rate down to ×0.1 fits; at ×0.1 the latest clip end that \
             fits is {end} ticks"
        ))
    }

    /// R3: `after` is the clip once `what` (`retiming action 7`, `removing
    /// action 7`, `removing action 7's end rate`) is done. `None` when it
    /// fits.
    pub(crate) fn overrun_refusal(&self, after: &Clip, what: &str) -> Option<String> {
        let over = self.overrun(after)?;
        let end = self.latest_fitting_end(after);
        Some(format!(
            "{what} would read clip {} {over} ticks past the end of its media; the latest clip \
             end that fits is {end} ticks",
            after.id
        ))
    }
}

/// **The readout is the CORE's answer, not a copy of it** (D4-6, D2-1), as the
/// Speed sheet's is: every change runs one trial `applying` of the op Apply
/// would send on the edited project and reads it back — the base rate from
/// `clip_state`'s `speed` before the edit, the target and the return from the
/// new actions' `end.speed`, the hold from their spans. A refusal or an error
/// prints the core's own sentence and disables Apply, so the sheet shows the
/// refusal before it applies. No rate is computed here.
final class SpeedRampSheetController: NSViewController, NSTextFieldDelegate {
    /// Weak, like every sheet's back-reference: the document must be free to
    /// close even with a dialog mid-air.
    private weak var document: ProjectDocument?
    /// The clip's id, not a snapshot: the document replaces its snapshot on
    /// every edit (`SpeedSheetController`'s reasoning).
    private let clip: UInt32
    /// CLIP time, or nil for the whole clip.
    private let span: (from: Ticks, to: Ticks)?

    private let shapePopup = NSPopUpButton(frame: .zero, pullsDown: false)
    private let rateField = NSTextField(string: "")
    private let presetPopup = NSPopUpButton(frame: .zero, pullsDown: true)
    private let curvePopup = NSPopUpButton(frame: .zero, pullsDown: false)
    private let holdPopup = NSPopUpButton(frame: .zero, pullsDown: false)
    private let readoutLabel = NSTextField(wrappingLabelWithString: "")
    private var applyButton: NSButton?

    /// A dip's and a burst's hold choices, as fractions of the span: "None",
    /// "25%", "50%" (the default, the core's own) and "75%".
    static let holds: [Double] = [0, 0.25, 0.5, 0.75]
    /// The shape the sheet opens on: a dip fits a clip already playing its
    /// whole media, where a rise past the base rate would overrun.
    static let initialShape: SpeedRampShape = .speedDip
    static let initialHold: Double = 0.5

    init(document: ProjectDocument, clip: UInt32, span: (from: Ticks, to: Ticks)?) {
        self.document = document
        self.clip = clip
        self.span = span
        super.init(nibName: nil, bundle: nil)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("SpeedRampSheetController does not support NSCoder")
    }

    // MARK: - The sheet's arithmetic

    /// The rate a shape opens at: ×2 up and burst, ×0.5 down and dip.
    static func defaultRate(for shape: SpeedRampShape) -> Double {
        switch shape {
        case .rampUp, .speedBurst: return 2
        case .rampDown, .speedDip: return 0.5
        }
    }

    /// `range` as clip time when it lies inside `clip` (start at or after the
    /// clip's start, end at or before its end, end after start); nil — the
    /// whole clip — otherwise (SR-24 (b)).
    static func span(
        of clip: ClipSnapshot, range: (start: Ticks, end: Ticks)?
    ) -> (from: Ticks, to: Ticks)? {
        guard let range, range.end > range.start, range.start >= clip.start,
            range.end <= clip.end
        else { return nil }
        return (range.start - clip.start, range.end - clip.start)
    }

    /// The op Apply sends and the readout tries: `hold` only for a dip or a
    /// burst, `from`/`to` only for a span.
    static func op(
        clip: UInt32, shape: SpeedRampShape, rate: Double, curve: Curve, hold: Double,
        span: (from: Ticks, to: Ticks)?
    ) -> ReelOp {
        .addSpeedRamp(
            clip: clip, shape: shape, rate: rate, from: span?.from, to: span?.to, curve: curve,
            hold: shape.holds ? hold : nil)
    }

    struct Readout: Equatable {
        let lines: [String]
        let canApply: Bool
    }

    /// Line 1 names the shape and the span in timeline timecode; line 2 is
    /// the trial's rates (and a dip's or a burst's hold), or the core's
    /// sentence with Apply disabled.
    static func readout(
        of op: ReelOp, clip: UInt32, shape: SpeedRampShape, span: (from: Ticks, to: Ticks)?,
        in project: ReelProject
    ) -> Readout {
        let snapshot = project.snapshot
        guard let target = snapshot.clip(clip) else { return Readout(lines: [], canApply: false) }
        let fps = snapshot.canvas.fps
        let from = target.start + (span?.from ?? 0)
        let to = span.map { target.start + $0.to } ?? target.end
        let place = span == nil ? "the whole clip" : "the range"
        let head =
            "\(shape.displayName) · \(place) " + ReelTime.format(from, fps: fps, frames: true)
            + " – " + ReelTime.format(to, fps: fps, frames: true)
        let trial: ReelEdit
        do {
            trial = try project.applying(op)
        } catch {
            let message = (error as? ReelCoreError)?.message ?? error.localizedDescription
            return Readout(lines: [head, message], canApply: false)
        }
        switch trial {
        case .identity:
            return Readout(lines: [head], canApply: false)
        case .refused(let refusal):
            return Readout(lines: [head, refusal.reason], canApply: false)
        case .applied(let after):
            let before = Set(target.actions.map(\.id))
            let added = (after.snapshot.clip(clip)?.actions ?? [])
                .filter { !before.contains($0.id) }
                .sorted { $0.start < $1.start }
            let base = project.clipState(clip, at: from)?["speed"] as? Double
            func rate(_ value: Double?) -> String {
                value.map { "×" + String(format: "%g", $0) } ?? "×?"
            }
            var line = rate(base) + " → " + rate(added.first?.end.speed)
            if added.count == 2 {
                let held = added[1].start - (added[0].start + added[0].duration)
                line += ", held " + String(format: "%.2f", ReelTime.seconds(held)) + " s, → "
                    + rate(added[1].end.speed)
            }
            return Readout(lines: [head, line], canApply: true)
        }
    }

    // MARK: - View

    override func loadView() {
        for shape in SpeedRampShape.allCases {
            shapePopup.menu?.addItem(menuItem(shape.displayName, shape.rawValue))
        }
        select(shapePopup, SpeedRampSheetController.initialShape.rawValue)
        shapePopup.font = DS.sans(13)
        shapePopup.target = self
        shapePopup.action = #selector(shapeChosen(_:))

        SpeedRateControls.styleRateField(
            rateField, initial: Self.defaultRate(for: Self.initialShape), delegate: self)
        SpeedRateControls.fillPresets(
            presetPopup, target: self, action: #selector(presetChosen(_:)))

        for curve in [Curve.easeInOut, Curve.linear] {
            curvePopup.menu?.addItem(menuItem(curve.displayName, curve.rawValue))
        }
        select(curvePopup, Curve.easeInOut.rawValue)
        curvePopup.font = DS.sans(13)
        curvePopup.target = self
        curvePopup.action = #selector(controlChanged(_:))

        for hold in Self.holds {
            let title = hold == 0 ? "None" : String(format: "%.0f%%", hold * 100)
            holdPopup.menu?.addItem(menuItem(title, NSNumber(value: hold)))
        }
        if let item = holdPopup.itemArray.first(where: {
            ($0.representedObject as? NSNumber)?.doubleValue == Self.initialHold
        }) {
            holdPopup.select(item)
        }
        holdPopup.font = DS.sans(13)
        holdPopup.target = self
        holdPopup.action = #selector(controlChanged(_:))

        readoutLabel.font = DS.mono(11)
        readoutLabel.textColor = DS.textMuted
        readoutLabel.preferredMaxLayoutWidth = sheetWidth - sheetInset * 2

        let rateRow = SpeedRateControls.rateRow(field: rateField, presets: presetPopup)

        let grid = makeSheetGrid([
            [fieldLabel("Shape:"), shapePopup],
            [fieldLabel("Rate:"), rateRow],
            [fieldLabel("Curve:"), curvePopup],
            [fieldLabel("Hold:"), holdPopup],
        ])

        let content = sheetColumn([grid, readoutLabel])

        let cancelButton = sheetCancelButton(target: self, action: #selector(cancelClicked(_:)))
        let apply = sheetApplyButton(target: self, action: #selector(applyClicked(_:)))
        applyButton = apply
        view = makeSheetView(
            title: "Speed Ramp",
            hint: "Up and Burst rise above the clip's rate where the ramp starts; Down and Dip "
