    /// registration; the notification carries `["isLive": true]`.
    func updateLiveEdit(_ op: ReelOp) {
        updateLiveEdit([op])
    }

    func updateLiveEdit(_ ops: [ReelOp]) {
        guard let base = liveEditBase else { return }
        guard case .applied(let updated)? = try? base.applying(addressed(ops)) else {
            // **Every answer but `.applied` is swallowed on purpose** — an
            // invalid tick, an identity and a rule's refusal alike (spec #8's
            // eighth decision). A refused tick is NORMAL here and recovers on
            // the next one; the last good frame stays. Not chatty.
            return
        }
        project = updated
        projectDidChange(isLive: true)
    }

    /// ONE undo step from the `beginLiveEdit` snapshot to the current handle —
    /// none when no tick applied (`updateLiveEdit` swaps only on `.applied`) —
    /// or, `cancelled` (Esc on the canvas, spec §11 CI-16), the snapshot put
    /// back with no step and no change count; then `["isLive": false]` either
    /// way, so listeners that skipped the ticks refresh once.
        commitEdit(actionName, ops, grouped: true)
    }

    /// Four answers (spec §5.5): `.applied` registers undo and publishes,
    /// `.identity` and `.refused` are BOTH a beep and no undo step — a
    /// refusal also posts `projectDocumentDidRefuse` with its sentence (spec
    /// §11 CI-10) — and a throw is the core's own message. `ReelEdit` argues
    /// the middle two. Only `.applied` opens the explicit group: an empty one
    /// is still a step on the stack, and closing it clears redo (#59).
    private func commitEdit(_ actionName: String, _ ops: [ReelOp], grouped: Bool) {
        let current = project
        do {
            switch try current.applying(addressed(ops)) {
            case .applied(let updated):
                func commit() {
                    registerUndo(restoring: current, actionName: actionName)
                    project = updated
                    countEditChange(.changeDone)
                    projectDidChange()
                }
                if grouped { inExplicitUndoGroup(commit) } else { commit() }
            case .identity:
                NSSound.beep()
            case .refused(let refusal):
                // The identity's beep and NO undo step, then the sentence.
                NSSound.beep()
                NotificationCenter.default.post(
                    name: .projectDocumentDidRefuse, object: self,
                    userInfo: ["refusal": refusal])
            }
        } catch {
            present(error)
        }
    }

